import java.util.*;

class Solution {
    public int[][] nearestZero(int[][] grid) {
        int r = grid.length, c = grid[0].length;
        int[][] dist = new int[r][c];
        ArrayDeque<int[]> q = new ArrayDeque<>();
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++) {
                if (grid[i][j] == 0) { dist[i][j] = 0; q.add(new int[]{i, j}); } // every zero is a source
                else dist[i][j] = -1; // not reached yet
            }
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            for (int[] d : dirs) {
                int x = cur[0] + d[0], y = cur[1] + d[1];
                if (x >= 0 && y >= 0 && x < r && y < c && dist[x][y] == -1) {
                    dist[x][y] = dist[cur[0]][cur[1]] + 1; // first visit = shortest
                    q.add(new int[]{x, y});
                }
            }
        }
        return dist;
    }
}

