                    d[i][j] = 0; q.append((i, j))
        while q:
            i, j = q.popleft()
            for x, y in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
                if 0 <= x < r and 0 <= y < c and d[x][y] < 0:
                    d[x][y] = d[i][j] + 1; q.append((x, y))
        return d

