function nearestZero(grid) {
  const r = grid.length, c = grid[0].length, d = grid.map(row => row.map(() => -1)), q = [];
  for (let i = 0; i < r; i++) for (let j = 0; j < c; j++) if (grid[i][j] === 0) { d[i][j] = 0; q.push([i, j]); }
  for (let h = 0; h < q.length; h++) {
    const [i, j] = q[h];
    for (const [x, y] of [[i+1,j],[i-1,j],[i,j+1],[i,j-1]])
      if (x >= 0 && x < r && y >= 0 && y < c && d[x][y] < 0) { d[x][y] = d[i][j] + 1; q.push([x, y]); }
  }
  return d;
}
